/*
 * WHAT IS WAITING FOR THE COACH (DBU-08): the one owner of the inbox's rules.
 *   request { at }   coachInbox (the Inbox page, the Inbox tab's count) and morningRound (the digest)
 * Answers `items`, oldest first with check-ins last, and `learners`: the facts morningRound decides
 * "gone quiet" from. Only learners whose plan is active count.
 *
 *   review    the newest version of a homework's hand-in is pending (the step is handed in).
 *             since = when it was handed in.
 *   question  the newest message in a learner's conversation is hers, and the coach has not marked it
 *             "No reply needed" (settledAt). A reply ends it; reading it does not.
 *             since = the first of her messages since the coach last wrote or marked one settled.
 *   quiet     an open QuietFlag (only morningRound raises one), not snoozed, with a reason that still holds:
 *             inactive while she has done nothing after the flag's lastActiveAt; overdue while that
 *             homework is still shared, not started and due when it was flagged.
 *             since = when it was raised, or when its snooze ended.
 *   checkin   (DBU-10) she answered a check-in and the coach has not pressed Done (seenAt). LOW
 *             PRIORITY: listed after every other kind, oldest first among themselves, because nothing
 *             waits on the coach's answer. Carries the response's own copy of the form and the answers.
 *             since = when she answered.
 * Activity is the latest of: the account's lastSeenAt (myUnread stamps it from every learner page),
 * a message she wrote, a version she handed in, a check-in she answered.
 * Fails (`failed`) rather than answer a partial list.
 */
if (Inputs.request !== undefined && Inputs.request !== null) {
  (async () => {
    try {
      const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
      const now = Date.now();
      const t = (iso) => { const n = Date.parse(iso || ''); return Number.isFinite(n) ? n : 0; };
      const latest = (list) => list.filter(Boolean).sort((a, b) => t(a) - t(b)).pop() || null;
      const byCreated = (a, b) => String(a.createdAt).localeCompare(String(b.createdAt));
      const excerpt = (s) => { const one = String(s || '').replace(/\s+/g, ' ').trim(); return one.length > 160 ? one.slice(0, 157).trimEnd() + '…' : one; };
      const pick = (row, fields) => {
        const out = { id: row.objectId };
        fields.forEach((f) => { out[f] = row[f] === undefined ? null : row[f]; });
        return out;
      };
      // The same shape learnerAsCoach gives Work/Versions.
      const pickSub = (s) => Object.assign(pick(s, ['step', 'version', 'kind', 'files', 'url', 'text', 'note', 'review', 'reviewNote', 'reviewedAt']), { handedInAt: s.createdAt });

      const plans = await q('Plan', { status: { equalTo: 'active' } });
      const learnerIds = [...new Set(plans.map((p) => p.learner).filter(Boolean))];
      const items = [];
      const learners = [];
      if (learnerIds.length) {
        const inIds = { containedIn: learnerIds };
        const [users, steps, subs, msgs, checkins, flags] = await Promise.all([
          q('_User', { objectId: inIds }),
          q('Step', { learner: inIds }),
          q('Submission', { learner: inIds }),
          q('Message', { learner: inIds }),
          q('CheckinResponse', { learner: inIds }),
          q('QuietFlag', { learner: inIds })
        ]);
        for (const id of learnerIds) {
          const plan = plans.filter((p) => p.learner === id).sort((a, b) => String(b.startedOn).localeCompare(String(a.startedOn)))[0];
          const user = users.find((u) => u.objectId === id);
          if (!user || !plan) continue;
          const name = String(user.name || user.email || '');
          const base = { learnerId: id, learner: name, first: name.split(' ')[0] };
          const mySteps = steps.filter((s) => s.plan === plan.objectId).sort((a, b) => a.position - b.position);
          const mySubs = subs.filter((s) => s.learner === id);
          const myMsgs = msgs.filter((m) => m.learner === id).sort(byCreated);

          // To review: the newest version of a handed-in homework, while it waits.
          for (const s of mySteps) {
            if (s.kind !== 'homework' || s.status !== 'handed_in') continue;
            const versions = mySubs.filter((v) => v.step === s.objectId).sort((a, b) => a.version - b.version);
            const newest = versions[versions.length - 1];
            if (!newest || newest.review !== 'pending') continue;
            items.push(Object.assign({
              id: 'review-' + newest.objectId, kind: 'review', since: newest.createdAt,
              stepId: s.objectId, title: String(s.title || ''), version: newest.version, submissionKind: newest.kind,
              submissions: versions.map(pickSub)
            }, base));
          }

          // A question: her message is the newest, and not settled.
          const last = myMsgs[myMsgs.length - 1];
          if (last && last.author === id && !last.settledAt) {
            let i = myMsgs.length - 1;
            while (i > 0 && myMsgs[i - 1].author === id && !myMsgs[i - 1].settledAt) i -= 1; // a settled one closed the last run
            const step = last.step ? mySteps.find((s) => s.objectId === last.step) : null;
            items.push(Object.assign({
              id: 'question-' + last.objectId, kind: 'question', since: myMsgs[i].createdAt,
              messageId: last.objectId, count: myMsgs.length - i, body: excerpt(last.body),
              attachments: (Array.isArray(last.attachments) ? last.attachments : []).length,
              stepId: step ? step.objectId : '', title: step ? String(step.title || '') : ''
            }, base));
          }

          // A check-in answered, until the coach presses Done (DBU-10).
          for (const r of checkins.filter((c) => c.learner === id && !c.seenAt)) {
            const s = mySteps.find((x) => x.objectId === r.step);
            if (!s) continue;
            items.push(Object.assign({
              id: 'checkin-' + r.objectId, kind: 'checkin', since: r.createdAt,
              responseId: r.objectId, stepId: s.objectId, title: String(s.title || ''),
              form: r.form || s.form || { questions: [] }, answers: r.answers || {}
            }, base));
          }

          // The facts: what she last did, what is overdue, what is booked.
          const lastActiveAt = latest([
            user.lastSeenAt,
            ...myMsgs.filter((m) => m.author === id).map((m) => m.createdAt),
            ...mySubs.map((s) => s.createdAt),
            ...checkins.filter((c) => c.learner === id).map((c) => c.createdAt)
          ]);
          const overdue = mySteps
            .filter((s) => s.kind === 'homework' && s.shared === true && s.status === 'not_started' && s.dueAt && t(s.dueAt) < now)
            .map((s) => ({ stepId: s.objectId, title: String(s.title || ''), dueAt: s.dueAt }));
          const booked = mySteps
            .filter((s) => s.kind === 'live' && s.status === 'booked' && t(s.startsAt) > now)
            .sort((a, b) => t(a.startsAt) - t(b.startsAt))[0];
          const facts = {
            learnerId: id, learner: name, startedOn: plan.startedOn || null, lastSeenAt: user.lastSeenAt || null,
            lastActiveAt, overdue, nextSession: booked ? booked.startsAt : null
          };
          learners.push(facts);

          // Gone quiet: an open flag, not snoozed, with a reason that still holds.
          for (const f of flags.filter((x) => x.learner === id && !x.closedAt)) {
            if (f.snoozedUntil && t(f.snoozedUntil) > now) continue;
            const holding = (Array.isArray(f.reasons) ? f.reasons : []).filter((r) => {
              if (r && r.kind === 'inactive') return !(lastActiveAt && t(lastActiveAt) > t(r.lastActiveAt));
              if (r && r.kind === 'overdue') {
                const s = mySteps.find((x) => x.objectId === r.stepId);
                return !!s && s.shared === true && s.status === 'not_started' && s.dueAt === r.dueAt;
              }
              return false;
            });
            if (!holding.length) continue;
            items.push(Object.assign({
              id: 'quiet-' + f.objectId, kind: 'quiet', since: latest([f.raisedAt, f.snoozedUntil]),
              flagId: f.objectId, reasons: holding, nudgedAt: f.nudgedAt || null, facts
            }, base));
          }
        }
      }
      const low = (i) => (i.kind === 'checkin' ? 1 : 0);
      items.sort((a, b) => (low(a) - low(b)) || (t(a.since) - t(b.since)));
      Outputs.items = items;
      Outputs.count = items.length;
      Outputs.learners = learners;
      Outputs.done();
    } catch (e) {
      console.error('[dbu:Inbox items] ' + String((e && e.message) || e));
      Outputs.failed();
    }
  })();
}
